<?php
namespace App\Controllers; use App\Helpers\{View,Csrf,Flash}; use App\Middlewares\AdminMiddleware; use App\Config\Database;
final class AdminRewardController {public function index():void{AdminMiddleware::handle();View::render('admin/rewards',['title'=>'Recompensas','rewards'=>Database::connection()->query('SELECT * FROM rewards ORDER BY points_required')->fetchAll()]);}public function store():void{AdminMiddleware::handle();Csrf::validate();$s=Database::connection()->prepare("INSERT INTO rewards(name,points_required,discount_percent,status) VALUES(?,?,?,'ACTIVE')");$s->execute([trim($_POST['name']??''),max(1,(int)($_POST['points_required']??1)),min(100,max(0,(float)($_POST['discount_percent']??0)))]);Flash::set('success','Recompensa creada.');header('Location: /admin/rewards');}public function toggle(string $id):void{AdminMiddleware::handle();Csrf::validate();Database::connection()->prepare("UPDATE rewards SET status=IF(status='ACTIVE','INACTIVE','ACTIVE') WHERE id=?")->execute([(int)$id]);header('Location: /admin/rewards');}}
